package ara.daily;
import org.json.*;import java.util.*;import java.security.*;import java.nio.charset.StandardCharsets;
final class DiaryQueue {
 private DiaryQueue(){}
 static String canonical(Object value)throws Exception{if(value instanceof JSONObject){JSONObject o=(JSONObject)value;List<String> keys=new ArrayList<>();Iterator<String> it=o.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys);StringBuilder b=new StringBuilder("{");for(String k:keys){if(b.length()>1)b.append(',');b.append(JSONObject.quote(k)).append(':').append(canonical(o.get(k)));}return b.append('}').toString();}if(value instanceof JSONArray){JSONArray a=(JSONArray)value;StringBuilder b=new StringBuilder("[");for(int i=0;i<a.length();i++){if(i>0)b.append(',');b.append(canonical(a.get(i)));}return b.append(']').toString();}String s=new JSONArray().put(value).toString();return s.substring(1,s.length()-1);}
 static String hash(JSONObject payload)throws Exception{byte[] h=MessageDigest.getInstance("SHA-256").digest(canonical(payload).getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte v:h)b.append(String.format(Locale.ROOT,"%02x",v&255));return b.toString();}
 static JSONObject items(JSONObject root)throws Exception{JSONObject items=root.optJSONObject("items");if(items==null){items=new JSONObject();root.put("items",items);}return items;}
 static boolean put(JSONObject root,JSONObject payload)throws Exception{if(!"diary".equals(payload.optString("op")))throw new java.io.IOException("일기 저장 요청만 대기시킬 수 있습니다.");String date=NotionDaily.date(payload),hash=hash(payload);boolean active=NotionDiary.active(payload);JSONObject old=items(root).optJSONObject(date);if(old!=null&&hash.equals(old.optString("hash"))&&old.optBoolean("skipped")==!active)return false;JSONObject item=old==null?new JSONObject():old;item.put("payload",new JSONObject(payload.toString())).put("hash",hash).put("skipped",!active).put("retryAt",0).put("attempts",0).put("error","");items(root).put(date,item);return true;}
 static boolean pending(JSONObject item,String target){return !item.optBoolean("skipped")&&(!item.optString("hash").equals(item.optString("syncedHash"))||!target.equals(item.optString("syncedTarget")));}
 static void done(JSONObject root,String date,String expected,String target,long now)throws Exception{JSONObject item=items(root).optJSONObject(date);if(item!=null&&expected.equals(item.optString("hash"))){item.put("syncedHash",expected).put("syncedTarget",target).put("lastSyncedAt",now).put("error","").put("attempts",0).put("retryAt",0);root.put("lastSyncedAt",now).put("lastDate",date).put("error","");}}
 static void fail(JSONObject root,String date,String expected,String error,long now)throws Exception{JSONObject item=items(root).optJSONObject(date);if(item!=null&&expected.equals(item.optString("hash"))){int attempts=item.optInt("attempts")+1;item.put("error",error).put("attempts",attempts).put("retryAt",now+Math.min(900000L,15000L*(1L<<Math.min(attempts,6))));root.put("error",error);}}
}
